/**
 * Question bank schema (US-7.1, US-7.2, FR-21; ADR-0001 "Content").
 *
 * Zod is used at build/CI time only and must never be imported from `src/`.
 * Shape rules live here; rules that need several fields or several files
 * (option counts per type, `correct` reference, duplicates, retired IDs, topic
 * membership) live in `rules.ts` so each error can name its exact field.
 *
 * Versioning: every content file carries `schemaVersion`. A breaking change to
 * this shape bumps CONTENT_SCHEMA_VERSION and needs a migration of all files in
 * the same PR. `contentVersion` is build-generated by T-06, not stored here.
 */
import { z } from "zod";

export const CONTENT_SCHEMA_VERSION = 1;

/** Stable slug ID (QA flag F-1). */
export const SLUG_PATTERN = /^[a-z0-9]+(-[a-z0-9]+)*$/;

export const DIFFICULTIES = ["easy", "medium", "hard"] as const;
export const QUESTION_TYPES = ["single-choice", "true-false"] as const;
export const REVIEW_STATUSES = ["draft", "reviewed"] as const;

export const SINGLE_CHOICE_OPTION_IDS = ["a", "b", "c", "d"] as const;
export const SINGLE_CHOICE_MIN_OPTIONS = 3;
export const SINGLE_CHOICE_MAX_OPTIONS = 4;
/** True/false options: exact ids and display texts. */
export const TRUE_FALSE_OPTIONS = [
  { id: "true", text: "True" },
  { id: "false", text: "False" },
] as const;

export const MIN_EXPLANATION_LENGTH = 20;

const slug = z.string().regex(SLUG_PATTERN, {
  error: `must be a kebab-case slug matching ${SLUG_PATTERN.source}`,
});

const nonBlank = z
  .string()
  .refine((value) => value.trim().length > 0, { error: "must not be empty" });

const schemaVersion = z.literal(CONTENT_SCHEMA_VERSION, {
  error: `unsupported schemaVersion; expected ${String(CONTENT_SCHEMA_VERSION)}`,
});

/** https-only source link, parsed with the WHATWG URL parser. */
const httpsUrl = z.string().superRefine((value, ctx) => {
  let url: URL;
  try {
    url = new URL(value);
  } catch {
    ctx.addIssue({ code: "custom", message: "must be a valid absolute URL" });
    return;
  }
  if (url.protocol !== "https:") {
    ctx.addIssue({
      code: "custom",
      message: `must use https (found "${url.protocol}")`,
    });
  } else if (url.username !== "" || url.password !== "") {
    ctx.addIssue({ code: "custom", message: "must not contain credentials" });
  }
});

/** Option text must be trimmed (T-32 N7); blank text reports "empty" only. */
const optionText = nonBlank.refine(
  (value) => value.trim() === "" || value === value.trim(),
  { error: "must not have leading or trailing whitespace" },
);

export const optionSchema = z.strictObject({
  id: nonBlank,
  text: optionText,
});

export const questionSchema = z.strictObject({
  id: slug,
  topic: slug,
  difficulty: z.enum(DIFFICULTIES),
  type: z.enum(QUESTION_TYPES),
  prompt: nonBlank,
  options: z.array(optionSchema),
  correct: z.string({ error: "must be a single option id (string)" }),
  explanation: z
    .string()
    .refine((value) => value.trim().length >= MIN_EXPLANATION_LENGTH, {
      error: `must be at least ${String(MIN_EXPLANATION_LENGTH)} characters`,
    }),
  sourceUrl: httpsUrl,
  reviewStatus: z.enum(REVIEW_STATUSES),
  // Required (non-empty) only when reviewStatus is "reviewed"; see rules.ts.
  reviewedBy: z.string().optional(),
});

/** One file per topic: content/questions/<topic-id>.json. */
export const questionFileSchema = z.strictObject({
  schemaVersion,
  // Each element is checked separately so one bad question does not hide
  // errors in the others.
  questions: z.array(z.unknown()),
});

export const topicsFileSchema = z.strictObject({
  schemaVersion,
  topics: z
    .array(z.strictObject({ id: slug, name: nonBlank }))
    .min(1, { error: "must list at least one topic" }),
});

export const retiredIdsFileSchema = z.strictObject({
  schemaVersion,
  retiredIds: z.array(slug),
});

export type Question = z.infer<typeof questionSchema>;
export type QuestionOption = z.infer<typeof optionSchema>;
export type Topic = z.infer<typeof topicsFileSchema>["topics"][number];
